import React, { useState } from "react";
import "./inpexp.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faXmark,
  faFileCode,
  faFileArrowDown,
  faLink,
  faAnchorLock,
} from "@fortawesome/free-solid-svg-icons";
import CryptoJS from "crypto-js";

export default function ExportJson(props) {
  const [receiverName, setReceiverName] = useState("");
  const [userName] = useState(localStorage.getItem("imuser") || "");
  // const [previewData, setPreviewData] = useState(null);
  // const [encryptedText, setEncryptedText] = useState("");

  // MUST match ImportJson generateKey
  const generateKey = (sender, receiver) => {
    const combined = `${sender.trim()}:${receiver.trim()}`;
    return CryptoJS.SHA256(combined).toString(); // full 64-char hash
  };

  const handleExport = () => {
    if (!userName) {
      props.notify(
        "Your username is missing. Please log in or set 'imuser' in localStorage."
      );
      return;
    }

    if (!receiverName.trim()) {
      props.notify("Please enter your friend's username (receiver).");
      return;
    }

    const rawData = localStorage.getItem("websiteData");

    if (!rawData) {
      props.notify("No links found to export. Add some links first.");
      return;
    }

    try {
      const parsed = JSON.parse(rawData);
      // setPreviewData(parsed);

      const key = generateKey(userName, receiverName);
      const cipherText = CryptoJS.AES.encrypt(
        JSON.stringify(parsed),
        key
      ).toString();

      // setEncryptedText(cipherText);

      const blob = new Blob([cipherText], {
        type: "text/plain;charset=utf-8",
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "savelinks_encrypted.txt";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      props.notify(
        `Encrypted file downloaded. Share it with "${receiverName.trim()}" along with both usernames.`
      );
    } catch (error) {
      console.error("Export / encrypt error:", error);
      props.notify(
        "Something went wrong while exporting. Check your data and try again."
      );
    }
  };

  return (
    <div
      className="addingCard"
      style={{ display: props.display ? "grid" : "none" }}
    >
      <div className="impexp">
        <FontAwesomeIcon
          icon={faXmark}
          className="close"
          onClick={() => props.setDisplay(false)}
        />

        <h2>
          Export links <FontAwesomeIcon icon={faLink} />
        </h2>

        <div className="btbox">
          <input
            className="inputRN"
            type="text"
            value={receiverName}
            onChange={(e) => setReceiverName(e.target.value)}
            placeholder="receiver's username"
          />

          <button onClick={handleExport}>
            Download Encrypted File <FontAwesomeIcon icon={faFileArrowDown} />
          </button>
        </div>

        <div className="infoBox">
          <p>
            You are logged in as:{" "}
            <span className="highlight">{userName || "Unknown"}</span>
          </p>
          <p>
            File will be saved as{" "}
            <span className="filename">
              savelinks_encrypted.txt <FontAwesomeIcon icon={faFileCode} />
            </span>
          </p>
          <p>Share this file and both usernames with your friend.</p>
          <p className="impo">
            Data is end-to-end encrypted <FontAwesomeIcon icon={faAnchorLock} />
          </p>
        </div>
      </div>
    </div>
  );
}
