import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faXmark, faUserPen, faCheck } from "@fortawesome/free-solid-svg-icons";
import { useRef, useEffect } from "react";

export default function User(props) {
  const [user, setUser] = useState("");
  const modalRef = useRef();

  useEffect(() => {
    const handleEsc = (event) => {
      if (event.keyCode === 27) props.setSubmit(false);
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [props]);

  const handleBackdropClick = (e) => {
    if (modalRef.current && !modalRef.current.contains(e.target)) {
      props.setSubmit(false);
    }
  };

  const saveUser = () => {
    if (user.trim() === "") {
      props.notify("Please enter a nickname.");
      return;
    }
    localStorage.setItem("imuser", user);
    props.setUser(user);
    props.setSubmit(false);
    props.notify("New nickname " + user + " set!");
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      saveUser();
    }
  };

  return (
    <div
      className="addingCard"
      style={{ display: props.submit ? "flex" : "none" }}
      onClick={handleBackdropClick}
    >
      <div className="modal-content redesigned-user" ref={modalRef}>
        <div className="modal-header">
          <h3>
            <FontAwesomeIcon icon={faUserPen} style={{ marginRight: "10px", opacity: 0.7 }} />
            Define Identity
          </h3>
          <FontAwesomeIcon icon={faXmark} className="close-btn" onClick={() => props.setSubmit(false)} />
        </div>

        <div className="details redesigned">
          <div className="input-group">
            <label>Nickname or Username</label>
            <input
              type="text"
              className="inputun modern-input"
              placeholder="e.g., Master Programmer"
              autoFocus
              value={user}
              onChange={(e) => setUser(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>

          <div className="modal-footer">
            <button className="btn-cancel" onClick={() => props.setSubmit(false)}>
              Keep current
            </button>
            <button className="btn-save accent" onClick={saveUser}>
              <FontAwesomeIcon icon={faCheck} /> Set Nickname
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
