import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faLink,
  faCodeFork,
  faPaperPlane,
  faPenToSquare,
  faFileImport,
  faFileExport,
  faTrash,
  faSort,
  faDice,
  faSquareArrowUpRight
} from "@fortawesome/free-solid-svg-icons";
import { faGithub } from "@fortawesome/free-brands-svg-icons";

import ExportJson from "./ExportJson";
import ImportJson from "./ImportJson";

import "./Footer.css";
export default function Footer(props) {
  const [visible, setVisible] = useState(true);
  const del = () => {
    const turningOn = visible; // visible=true means currently OFF, so we're turning ON
    setVisible(!visible);
    props.del(turningOn);
    // If turning delete ON, turn edit OFF
    if (turningOn && props.isEditMode) {
      props.setIsEditMode(false);
    }
  };

  const [impf, setImpf] = useState(false);
  const [expf, setExpf] = useState(false);

  return (
    <>
      <div className="header">
        <div className="userbox">
          <FontAwesomeIcon
            icon={faPenToSquare}
            className="edit"
            onClick={() => {
              props.setv(true);
            }}
          />
          {props.user}'s links
        </div>
        <div className="inportbox">
          <div
            onClick={() => {
              props.setSortDisplay(true);
            }}
          >
            <FontAwesomeIcon icon={faSort} />
            <span className="tooltip sort">sort</span>
          </div>
          <div
            onClick={() => {
              props.setIsDraggable(!props.isDraggable);
              props.notify(
                props.isDraggable ? "Dragging disabled" : "Dragging enabled You can drag & arrange now",
                props.isDraggable ? "#1e1e1e" : "#1dff77"
              );
            }}
            style={{ color: props.isDraggable ? "#1dff77" : "black" }}
          >
            <FontAwesomeIcon icon={faDice} />
            <span className="tooltip arrange">Arrange</span>
          </div>
          {/* ── Edit mode toggle ── */}
          <div
            className={`edit-mode-btn ${props.isEditMode ? "edit-mode-active" : ""}`}
            onClick={() => {
              const turningOn = !props.isEditMode;
              props.setIsEditMode(turningOn);
              // If turning edit ON, turn delete OFF
              if (turningOn && !visible) {
                setVisible(true);
                props.del(false);
              }
              props.notify(
                turningOn ? "Edit mode on You can edit now" : "Edit mode off",
                turningOn ? "#4fc3f7" : "#1e1e1e"
              );
            }}
            title="Edit cards"
          >
            <FontAwesomeIcon icon={faPenToSquare} />
            <span className="tooltip edit-tooltip">Edit cards</span>
          </div>

          {/* ── Delete mode toggle ── */}
          <div onClick={del} style={{ color: visible ? "black" : "red" }}>
            <FontAwesomeIcon className="ic" icon={faTrash} />
            <span className="tooltip delete">Trash box</span>
          </div>
          <div
            onClick={() => {
              setImpf(true);
            }}
          >
            <FontAwesomeIcon className="ic fin" icon={faFileImport} />
            <span className="tooltip import">inport</span>
          </div>
          <div
            onClick={() => {
              setExpf(true);
            }}
          >
            <FontAwesomeIcon className="ic fex" icon={faFileExport} />
            <span className="tooltip export">export</span>
          </div>
        </div>
      </div>

      <div className="footer">
        <a
          href="https://github.com/praveenjadhav1510"
          target="_blank"
          rel="noreferrer"
        >
          {" "}
          <FontAwesomeIcon icon={faGithub} /> Github{" "}
        </a>
        <a
          href="https://github.com/praveenjadhav1510/save-links"
          target="_blank"
          rel="noreferrer"
        >
          {" "}
          <FontAwesomeIcon icon={faLink} /> App repo
        </a>
        <a
          href="https://github.com/praveenjadhav1510/save-links/fork"
          target="_blank"
          rel="noreferrer"
        >
          {" "}
          <FontAwesomeIcon icon={faCodeFork} /> codefock
        </a>
        <a href="mailto:praveenjadhav1510+githubSavelinks@gmail.com?subject=Feedback%20for%20Savelinks&amp;body=%3C--Your%20feedback--%3E">
          {" "}
          <FontAwesomeIcon icon={faPaperPlane} /> feedback
        </a>
        <a href="https://favicon-api-rho.vercel.app/">
          {" "}
          <FontAwesomeIcon icon={faSquareArrowUpRight} /> Favicon API
        </a>
      </div>

      <ImportJson
        setDisplay={setImpf}
        display={impf}
        refresh={props.refresh}
        notify={props.notify}
      />
      <ExportJson
        setDisplay={setExpf}
        display={expf}
        user={props.user}
        notify={props.notify}
      />
    </>
  );
}
