import "./App.css";
import Card from "./components/Card";
import AddCard from "./components/AddCard";
import Footer from "./components/Footer";
import User from "./components/User";
import Notifaction from "./components/Notifaction";
import SortCards from "./components/SortCards";
import { useState } from "react";
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  rectSortingStrategy,
} from "@dnd-kit/sortable";

function App() {
  const [storedData, setSoredData] = useState(
    localStorage.getItem("websiteData")
  );
  const [sortDisplay, setSortDisplay] = useState(false);
  const [sortType, setSortType] = useState("WebPage");
  const [submit, setSubmit] = useState(false);
  const [del, setdel] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);
  const [user, setUser] = useState(localStorage.getItem("imuser"));
  const [isDraggable, setIsDraggable] = useState(false);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      const oldIndex = data.findIndex((item) => item.url === active.id);
      const newIndex = data.findIndex((item) => item.url === over.id);

      const newData = arrayMove(data, oldIndex, newIndex);
      localStorage.setItem("websiteData", JSON.stringify(newData));
      setSoredData(JSON.stringify(newData));
    }
  };
  const refresh = () => {
    user === null ? setSubmit(true) : setSubmit(false);
    console.log("refreshed");
    setSoredData(localStorage.getItem("websiteData"));
  };
  const defaultData = [
    {
      name: "Chat GPT",
      url: "https://chatgpt.com/",
      iconUrl: "https://chatgpt.com//favicon.ico",
      color: "#1e1e1e",
      pagetype: "Generative-AI",
    },
  ];
  const data = storedData ? JSON.parse(storedData) : defaultData;

  // ── Notification queue ──
  const [notifQueue, setNotifQueue] = useState([]);

  const pushNotifaction = (message, color) => {
    const id = Date.now() + Math.random(); // unique key
    setNotifQueue((prev) => [...prev, { id, message, color }]);
    // auto-remove after animation finishes (~4 s)
    setTimeout(() => {
      setNotifQueue((prev) => prev.filter((n) => n.id !== id));
    }, 4000);
  };

  const dismissNotification = (id) => {
    setNotifQueue((prev) => prev.filter((n) => n.id !== id));
  };

  return (
    <div className="App">
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <SortableContext items={data.map((item) => item.url)} strategy={rectSortingStrategy}>
          {data.map((item) => (
            <Card
              key={item.url}
              id={item.url} // Add id for sortable
              name={item.name}
              url={item.url}
              iconUrl={item.iconUrl}
              color={item.color}
              pagetype={item.pagetype}
              sortType={sortType}
              del={del}
              isEditMode={isEditMode}
              data={data}
              carddeleted={del}
              refresh={refresh}
              notify={pushNotifaction}
              isDraggable={isDraggable}
            />
          ))}
        </SortableContext>
      </DndContext>
      <AddCard data={data} refresh={refresh} notify={pushNotifaction} />
      <Footer
        setv={setSubmit}
        del={setdel}
        refresh={refresh}
        user={user}
        notify={pushNotifaction}
        setSortDisplay={setSortDisplay}
        isDraggable={isDraggable}
        setIsDraggable={setIsDraggable}
        isEditMode={isEditMode}
        setIsEditMode={setIsEditMode}
      />
      <User
        setSubmit={setSubmit}
        submit={submit}
        setUser={setUser}
        notify={pushNotifaction}
      />
      <Notifaction
        queue={notifQueue}
        dismiss={dismissNotification}
      />
      <SortCards
        sortDisplay={sortDisplay}
        setSortDisplay={setSortDisplay}
        sortType={sortType}
        setSortType={setSortType}
      />
    </div>
  );
}

export default App;
