import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faXmarkCircle, faPenToSquare } from "@fortawesome/free-solid-svg-icons";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import EditCard from "./EditCard";

export default function Card(props) {
  const [iconUrl, setIconUrl] = useState(props.iconUrl);
  const [isEditing, setIsEditing] = useState(false);

  const deleteCard = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const filteredData = props.data.filter((item) => item.url !== props.url);
    localStorage.setItem("websiteData", JSON.stringify(filteredData));
    props.refresh();
    props.notify("Removed " + props.name, props.color);
  };

  const openEdit = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsEditing(true);
  };

  const handleError = () => setIconUrl("default.svg");

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: props.id, disabled: !props.isDraggable });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    display:
      props.sortType === "WebPage"
        ? "flex"
        : props.pagetype === props.sortType
        ? "flex"
        : "none",
    zIndex: isDragging ? 10 : 1,
    opacity: isDragging ? 0.6 : 1,
    cursor: props.isDraggable ? "grab" : "pointer",
  };

  /* card data object for EditCard */
  const cardData = {
    name: props.name,
    url: props.url,
    iconUrl: props.iconUrl,
    color: props.color,
    pagetype: props.pagetype,
  };

  return (
    <>
      <a
        ref={setNodeRef}
        href={props.carddeleted || props.isDraggable ? null : props.url}
        target="_blank"
        rel="noreferrer"
        style={style}
        className={isDragging ? "dragging" : ""}
        {...attributes}
        {...(props.isDraggable ? listeners : {})}
      >
        <div
          className="card"
          style={{
            background: props.color,
            boxShadow: "0px 0px 20px " + props.color + "80",
            position: "relative",
          }}
        >
          <div className="imgspace">
            <img src={iconUrl} alt="icon" onError={handleError} id="icon" />
          </div>
          <div className="card-name">
            <span>{props.name}</span>
          </div>

          {/* Edit button – visible when isEditMode is active */}
          <FontAwesomeIcon
            icon={faPenToSquare}
            onClick={openEdit}
            className="edit-mark"
            title="Edit card"
            style={{ display: props.isEditMode ? "block" : "none" }}
          />

          {/* Delete button */}
          <FontAwesomeIcon
            icon={faXmarkCircle}
            onClick={deleteCard}
            className="x-mark"
            style={{ display: props.del ? "block" : "none" }}
          />
        </div>
      </a>

      {/* Edit Modal */}
      {isEditing && (
        <EditCard
          card={cardData}
          data={props.data}
          onClose={() => setIsEditing(false)}
          refresh={props.refresh}
          notify={props.notify}
        />
      )}
    </>
  );
}
