import React from "react";
import "./sorter.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { useEffect } from "react";
import {
  faHeadphones,
  faHouse,
  faPlay,
  faScrewdriverWrench,
  faXmark,
  faGamepad,
  faBlog,
  faCloudArrowDown,
  faLock,
} from "@fortawesome/free-solid-svg-icons";

export default function SortCards(props) {

  useEffect(() => {
    const handleEsc = (event) => {
      if (event.keyCode === 27) props.setSortDisplay(false);
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [props]);

  return (
    <div
      className={`Card-sorter redesigned ${props.sortDisplay ? "visible" : ""}`}
    >
      <div className="sorter-header">
        <span>Filters</span>
        <FontAwesomeIcon icon={faXmark} className="close-sorter" onClick={() => props.setSortDisplay(false)} />
      </div>

      <div className="sorter-grid">
        {/* WebPage category */}
        <div
          className={`sorter-item ${props.sortType === "WebPage" ? "active" : ""}`}
          onClick={() => props.setSortType("WebPage")}
        >
          <FontAwesomeIcon icon={faHouse} className="icon" />
          <span className="label">All</span>
        </div>

        {/* Tools category */}
        <div
          className={`sorter-item ${props.sortType === "Tool" ? "active" : ""}`}
          onClick={() => props.setSortType("Tool")}
        >
          <FontAwesomeIcon icon={faScrewdriverWrench} className="icon" />
          <span className="label">Tools</span>
        </div>

        {/* AI category */}
        <div
          className={`sorter-item ${props.sortType === "AI" ? "active" : ""}`}
          onClick={() => props.setSortType("AI")}
        >
          <span className="icon-text">AI</span>
          <span className="label">AI</span>
        </div>

        {/* AV Media category (Audio/Video) */}
        <div
          className={`sorter-item multi ${props.sortType === "Multimedia" ? "active" : ""}`}
          onClick={() => props.setSortType("Multimedia")}
        >
          <div className="icon-stack">
            <FontAwesomeIcon icon={faHeadphones} />
            <FontAwesomeIcon icon={faPlay} />
          </div>
          <span className="label">Media</span>
        </div>

        {/* New categories */}
        <div
          className={`sorter-item ${props.sortType === "Games" ? "active" : ""}`}
          onClick={() => props.setSortType("Games")}
        >
          <FontAwesomeIcon icon={faGamepad} className="icon" />
          <span className="label">Games</span>
        </div>

        <div
          className={`sorter-item ${props.sortType === "Blogs" ? "active" : ""}`}
          onClick={() => props.setSortType("Blogs")}
        >
          <FontAwesomeIcon icon={faBlog} className="icon" />
          <span className="label">Blogs</span>
        </div>

        <div
          className={`sorter-item ${props.sortType === "D-Link" ? "active" : ""}`}
          onClick={() => props.setSortType("D-Link")}
        >
          <FontAwesomeIcon icon={faCloudArrowDown} className="icon" />
          <span className="label">Files</span>
        </div>

        <div
          className={`sorter-item ${props.sortType === "Privet" ? "active" : ""}`}
          onClick={() => props.setSortType("Privet")}
        >
          <FontAwesomeIcon icon={faLock} className="icon" />
          <span className="label">Private</span>
        </div>
      </div>
    </div>
  );
}
